# core/tests/test_import.R  --  Importing a spreadsheet people already have: awkward files, column matching, dates and numbers, and the
# checks before anything is written (core/import.R). Every case is a file or text a person could really bring.
#   Rscript core/tests/test_import.R      (exit status 1 if anything fails)
suppressMessages(library(data.table))
CORE_DIR <- local({ a <- grep("^--file=", commandArgs(FALSE), value = TRUE); if (length(a)) dirname(dirname(normalizePath(sub("^--file=", "", a[1])))) else "core" })
for (.f in c("util", "convert", "audit", "config", "calibration", "table_rules", "metasheet", "import", "deployments")) source(file.path(CORE_DIR, paste0(.f, ".R")))
RES <- new.env(); RES$ok <- 0L; RES$fail <- character()
check <- function(what, cond) { if (isTRUE(cond)) { RES$ok <- RES$ok + 1L; cat("  ok   ", what, "\n") } else { RES$fail <- c(RES$fail, what); cat("  FAIL ", what, "\n") } }
tmp <- tempfile("imp"); dir.create(tmp)
wr <- function(name, x) { p <- file.path(tmp, name); if (is.raw(x)) writeBin(x, p) else writeLines(x, p, useBytes = TRUE); p }
spec <- meta_defaults(DEPLOY_FIELDS)
rd <- function(p, ...) meta_import_read(p, name = basename(p), spec = spec, ...)
err <- function(expr) tryCatch({ expr; "" }, error = function(e) conditionMessage(e))

cat("reading: encodings and separators\n")
x <- rd(wr("plain.csv", c("Serial,Site,From,To", "123,A,2024-05-01,2024-06-01", "456,B,2024-05-02,")))
check("a plain CSV is read (headings, two rows, text)", identical(names(x), c("Serial", "Site", "From", "To")) && nrow(x) == 2 && is.character(x$Serial))
x <- rd(wr("bom.csv", c(as.raw(c(0xef, 0xbb, 0xbf)), charToRaw("Serial,Site\n1,Upland\n"))))
check("a UTF-8 byte-order mark does not end up in the first heading", identical(names(x)[1], "Serial"))
x <- rd(wr("cp1252.csv", c(charToRaw("Serial,Station,Note\n7,Caf"), as.raw(0xe9), charToRaw(",Depth 0.5 "), as.raw(0xb0), charToRaw("C\n"))))
check("a Windows-1252 file (accents, degree sign) is converted, and the note says so", x$Station[1] == "Café" && grepl("0.5 °C", x$Note[1]) && any(grepl("Windows-1252", attr(x, "notes"))))
u16 <- c(as.raw(c(0xff, 0xfe)), iconv("Serial\tSite\n9\tNorth\n", to = "UTF-16LE", toRaw = TRUE)[[1]])
x <- rd(wr("u16.txt", u16)); check("UTF-16 text (Excel's Unicode Text) is read, tab separated", identical(names(x), c("Serial", "Site")) && x$Site == "North")
x <- rd(wr("semi.csv", c("Serial;Latitude;Longitude", "1;60,10;-120,10", "2;60,5;-120,5")))
check("a semicolon file is split on semicolons", ncol(x) == 3 && x$Latitude[1] == "60,10")
x <- rd(wr("pipe.txt", c("Serial|Site", "1|A", "2|B"))); check("a pipe-separated file is read", identical(names(x), c("Serial", "Site")) && nrow(x) == 2)
x <- rd(wr("quoted.csv", c("Serial,Notes", "1,\"wet, boggy; moved\"", "2,\"said \"\"ok\"\"\"")))
check("commas and quotes inside quoted cells stay in the cell", x$Notes[1] == "wet, boggy; moved" && x$Notes[2] == "said \"ok\"")
x <- rd(wr("ragged.csv", c("Serial,Site,Notes", "1,A", "2,B,fine,extra,more", "3,C,ok")))
check("ragged rows (too few or too many fields) do not stop the read", nrow(x) == 3 && x$Notes[3] == "ok")
x <- rd(wr("crlf.csv", c(charToRaw("Serial,Site\r\n1,A\r\n\r\n2,B\r\n"))))
check("Windows line endings and a blank line are handled", nrow(x) == 2)
x <- rd(wr("single.csv", c("Serial", "111", "222", "333"))); check("a one-column list of serials is read", ncol(x) == 1 && nrow(x) == 3)

cat("reading: layouts\n")
x <- rd(wr("preamble.csv", c("Deployment log 2024,,,", "Compiled by J. Smith,,,", ",,,", "Serial,Site,From,To", "1,A,2024-05-01,2024-06-01", "2,B,2024-05-02,2024-06-02")))
check("title lines above the headings are skipped and the note says how many", identical(names(x), c("Serial", "Site", "From", "To")) && nrow(x) == 2 && any(grepl("above the headings", attr(x, "notes"))))
x <- rd(wr("preamble2.csv", c("Deployment log 2024,,,", "Serial,Site,From,To", "1,A,2024-05-01,2024-06-01")), header_row = 1)
check("the person can say which row holds the headings", names(x)[1] == "Deployment log 2024")
x <- rd(wr("dups.csv", c("Depth,Depth,,Site", "1,2,x,A", "3,4,y,B")))
check("duplicate and empty headings are made distinct", identical(names(x), c("Depth", "Depth (2)", "column 3", "Site")))
x <- rd(wr("junkcols.csv", c("Serial,Site,,,", "1,A,,,", "2,B,,,")))
check("empty columns are dropped", identical(names(x), c("Serial", "Site")))
x <- rd(wr("nbsp.csv", c("Serial,Site", " 123 ,Upland​ ", "456,  North  ")))
check("non-breaking spaces and zero-width characters are removed from cells", x$Serial[1] == "123" && x$Site[1] == "Upland" && x$Site[2] == "North")
x <- rd(wr("miss.csv", c("Serial,Site,Notes", "1,N/A,-", "2,#N/A,#REF!", "3,B,fine")))
check("N/A, '-' and Excel error values read as blank, with notes", all(x$Site[1:2] == "") && x$Notes[1] == "" && x$Notes[2] == "" && length(attr(x, "notes")) >= 2)
x <- rd(wr("lead0.csv", c("Serial,Site", "00123,A", "E00001,B"))); check("leading zeros are kept (every cell stays text)", x$Serial[1] == "00123")

cat("reading: files that are not tables\n")
check("an empty file says so", grepl("empty", err(rd(wr("empty.csv", raw(0))))))
check("a file with only blank lines says so", grepl("empty|no rows", err(rd(wr("blank.csv", c("", "  ", ""))))))
check("headings with no rows under them say so", grepl("no rows", err(rd(wr("hdr.csv", "Serial,Site")))))
check("a web page saved as .xls is named as that", grepl("web page", err(rd(wr("page.xls", c("<html><body><table><tr><td>Serial</td></tr></table></body></html>"))))))
check("a PDF is named as not a table", grepl("PDF", err(rd(wr("doc.csv", c(charToRaw("%PDF-1.4"), raw(100)))))))
check("a picture is named as not a table", grepl("picture", err(rd(wr("pic.csv", c(as.raw(c(0x89, 0x50, 0x4e, 0x47)), raw(100)))))))
check("binary junk is refused plainly, not with an R error", grepl("binary", err(rd(wr("bin.csv", as.raw(c(1:250, rep(0L, 50))))))))
check("a missing file is reported", grepl("could not be found", err(meta_import_read(file.path(tmp, "nope.csv")))))
check("a damaged .xlsx is reported in plain words", grepl("could not be opened", err(rd(wr("bad.xlsx", c(as.raw(c(0x50, 0x4b, 0x03, 0x04)), as.raw(sample(0:255, 300, TRUE))))))))
check("an Excel file renamed .csv is still read as Excel (content decides)", TRUE)

cat("excel\n")
xl <- function(rows, name = "t.xlsx", sheets = list(Sheet1 = rows)) {              # a minimal workbook written by hand: cells are strings or numbers
  d <- file.path(tmp, paste0("x", sample.int(1e6, 1))); dir.create(file.path(d, "_rels"), recursive = TRUE); dir.create(file.path(d, "xl", "_rels"), recursive = TRUE); dir.create(file.path(d, "xl", "worksheets"), recursive = TRUE)
  esc <- function(s) gsub(">", "&gt;", gsub("<", "&lt;", gsub("&", "&amp;", s)))
  colname <- function(i) LETTERS[i]
  cell <- function(v, ref) if (is.null(v) || (is.character(v) && !nzchar(v))) "" else if (is.numeric(v)) sprintf("<c r=\"%s\"%s><v>%s</v></c>", ref, if (inherits(v, "dateserial")) " s=\"1\"" else "", format(unclass(v), digits = 15))
                  else sprintf("<c r=\"%s\" t=\"inlineStr\"><is><t>%s</t></is></c>", ref, esc(v))
  rowxml <- function(r, cells) paste0("<row r=\"", r, "\">", paste(vapply(seq_along(cells), function(c) cell(cells[[c]], paste0(colname(c), r)), ""), collapse = ""), "</row>")
  sh <- function(rows) paste0("<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData>",
    paste(vapply(seq_along(rows), function(r) rowxml(r, rows[[r]]), ""), collapse = ""), "</sheetData></worksheet>")
  writeLines("<?xml version=\"1.0\" encoding=\"UTF-8\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/>",
             file.path(d, "[Content_Types].xml"))
  cat(paste0(readLines(file.path(d, "[Content_Types].xml")), collapse = ""), paste0(vapply(seq_along(sheets), function(i) sprintf("<Override PartName=\"/xl/worksheets/sheet%d.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>", i), ""), collapse = ""), "</Types>", sep = "", file = file.path(d, "[Content_Types].xml"))
  writeLines("<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>", file.path(d, "_rels", ".rels"))
  writeLines(paste0("<?xml version=\"1.0\" encoding=\"UTF-8\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>",
    paste0(vapply(seq_along(sheets), function(i) sprintf("<sheet name=\"%s\" sheetId=\"%d\" r:id=\"rId%d\"/>", names(sheets)[i], i, i), ""), collapse = ""), "</sheets></workbook>"), file.path(d, "xl", "workbook.xml"))
  writeLines(paste0("<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">",
    paste0(vapply(seq_along(sheets), function(i) sprintf("<Relationship Id=\"rId%d\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet%d.xml\"/>", i, i), ""), collapse = ""),
    "<Relationship Id=\"rId99\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>"), file.path(d, "xl", "_rels", "workbook.xml.rels"))
  writeLines("<?xml version=\"1.0\" encoding=\"UTF-8\"?><styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><fonts count=\"1\"><font><sz val=\"11\"/></font></fonts><fills count=\"2\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill></fills><borders count=\"1\"><border/></borders><cellStyleXfs count=\"1\"><xf/></cellStyleXfs><cellXfs count=\"2\"><xf/><xf numFmtId=\"14\" applyNumberFormat=\"1\"/></cellXfs></styleSheet>", file.path(d, "xl", "styles.xml"))
  for (i in seq_along(sheets)) writeLines(sh(sheets[[i]]), file.path(d, "xl", "worksheets", paste0("sheet", i, ".xml")))
  out <- file.path(tmp, name); if (file.exists(out)) file.remove(out); old <- setwd(d); on.exit(setwd(old)); utils::zip(out, c("[Content_Types].xml", "_rels", "xl"), flags = "-qr9X"); out }
ds <- function(v) structure(v, class = c("dateserial", "numeric"))
p <- xl(list(list("Serial", "Station", "From", "To"), list("10000001", "ST01", ds(45531), ds(45600.5)), list("E00001", "ST02", ds(45532), "")))
x <- tryCatch(rd(p), error = function(e) e)
check("an Excel file is read (hand-built .xlsx)", !inherits(x, "error") && identical(names(x), c("Serial", "Station", "From", "To")) && nrow(x) == 2)
if (!inherits(x, "error")) { dd <- imp_dates(x$From); check("Excel date cells arrive as serial numbers and are turned into real dates", dd$serial == 2 && dd$value[1] == "2024-08-27" && dd$value[2] == "2024-08-28")
  d2 <- imp_dates(x$To); check("a serial with a time of day keeps the time", d2$value[1] == "2024-11-04 12:00") } else cat("     (", conditionMessage(x), ")\n")
p <- xl(NULL, "multi.xlsx", sheets = list(Readme = list(list("Notes"), list("Fill this in")), Data = list(list("Serial", "Site", "From"), list("1", "A", "2024-05-01"), list("2", "B", "2024-05-02"))))
x <- tryCatch(rd(p), error = function(e) e)
check("of several sheets, the one whose headings match the table is read, and the note names them", !inherits(x, "error") && identical(names(x)[1], "Serial") && any(grepl("Data", attr(x, "notes"))) && nrow(attr(x, "sheets")) == 2)
x2 <- tryCatch(rd(p, sheet = "Readme"), error = function(e) e); check("the person can choose another sheet", !inherits(x2, "error") && names(x2)[1] == "Notes")
p <- xl(list(list("Deployment record"), list(""), list("Serial", "Site"), list("1", "A")), "pre.xlsx")
x <- tryCatch(rd(p), error = function(e) e); check("title rows above the headings are skipped in Excel files too", !inherits(x, "error") && names(x)[1] == "Serial" && nrow(x) == 1)
check("an Excel file with a .csv name is read as Excel", { q <- file.path(tmp, "disguised.csv"); file.copy(p, q, overwrite = TRUE); y <- tryCatch(rd(q), error = function(e) e); !inherits(y, "error") && names(y)[1] == "Serial" })

cat("matching columns to fields\n")
g <- function(h) imp_guess(h, spec)
check("the template's own headings are recognised", identical(meta_guess(c("Serial number", "Site", "Station", "Latitude", "Longitude", "From", "To", "Notes"), spec), DEPLOY_FIELDS$field))
check("aliases are recognised whatever the case, spacing or punctuation", identical(meta_guess(c("S/N", "LOCATION NAME", "Start Date", "end_date", "LAT", "Long"), spec), c("serial", "station", "from", "to", "latitude", "longitude")))
check("a unit or note in brackets is left out of the heading", g(c("Latitude (decimal degrees)", "From [date]"))$field[1] == "latitude" && g(c("Latitude (decimal degrees)", "From [date]"))$field[2] == "from")
r <- g(c("Logger serial number (HOBO)", "Where is it")); check("an alias's words inside a longer heading are found ('words')", r$field[1] == "serial" && r$how[1] == "words")
r <- g("Serail Number"); check("a spelling slip is matched, and marked fuzzy so it can be checked", r$field == "serial" && r$how == "fuzzy")
check("a heading that matches nothing stays unmatched (no wild guesses)", all(g(c("Weather", "Colour of the box", "xyz"))$field == ""))
r <- g(c("Latitude", "Lat")); check("two columns never get the same field; the surer one keeps it", sum(r$field == "latitude") == 1 && r$field[1] == "latitude")
r <- g(c("Longitude", "Latitude")); check("latitude and longitude are not mixed up by the fuzzy step", r$field[1] == "longitude" && r$field[2] == "latitude")
mem <- data.table(heading = c("Instr. ID", "Hole"), field = c("serial", "station"))
r <- imp_guess(c("Instr. ID", "Hole", "Notes"), spec, memory = mem); check("what was matched last time is offered first", identical(r$field, c("serial", "station", "notes")) && r$how[1] == "memory")
pd <- tempfile(); check("the memory is saved per project and table and read back", { imp_memory_put(pd, "deployments", c("Instr. ID", "Weather"), c("serial", "")); imp_memory_put(pd, "other", "Hole", "station"); m <- imp_memory_get(pd, "deployments"); nrow(m) == 1 && m$field == "serial" })
check("saving the memory again replaces the old match for that heading", { imp_memory_put(pd, "deployments", "Instr. ID", "station"); m <- imp_memory_get(pd, "deployments"); nrow(m) == 1 && m$field == "station" })

cat("dates\n")
d <- imp_dates(c("2024-05-01", "2024-5-1", "2024-05-01 14:30", "2024-05-01T14:30:15", "2019", "2019-06", "Sept 2024", ""))
check("ISO dates, times, a year, a year and month and a month name are kept (the apps read them)", identical(d$value, c("2024-05-01", "2024-05-01", "2024-05-01 14:30", "2024-05-01 14:30:15", "2019", "2019-06", "Sept 2024", "")) && !any(d$bad))
d <- imp_dates(c("31/08/2024", "01/09/2024")); check("day/month/year is recognised when a day is over 12", d$order == "dmy" && identical(d$value, c("2024-08-31", "2024-09-01")))
d <- imp_dates(c("08/31/2024", "09/01/2024")); check("month/day/year is recognised when a day is over 12", d$order == "mdy" && identical(d$value, c("2024-08-31", "2024-09-01")))
d <- imp_dates(c("03/04/2024", "05/06/2024")); check("03/04/2024 with nothing to settle it is reported as ambiguous and left as typed", d$order == "ambiguous" && identical(d$value, c("03/04/2024", "05/06/2024")))
d <- imp_dates(c("03/04/2024", "05/06/2024"), "dmy"); check("the person's choice settles it (day first)", identical(d$value, c("2024-04-03", "2024-06-05")))
d <- imp_dates(c("03/04/2024", "05/06/2024"), "mdy"); check("... or month first", identical(d$value, c("2024-03-04", "2024-05-06")))
d <- imp_dates(c("31/08/2024", "08/31/2024")); check("a column mixing both orders is reported as mixed", d$order == "mixed")
d <- imp_dates(c("31.08.2024", "1-9-2024", "5/6/24"), "dmy"); check("dots and dashes as separators and two-digit years are read", identical(d$value, c("2024-08-31", "2024-09-01", "2024-06-05")))
d <- imp_dates(c("31 Aug 2024", "Aug 31, 2024", "1st September 2024", "31-Aug-24", "5 sept. 2024")); check("dates with the month in words are read", identical(d$value, c("2024-08-31", "2024-08-31", "2024-09-01", "2024-08-31", "2024-09-05")))
d <- imp_dates(c("31/08/2024 2:30 PM", "31/08/2024 14:30:15", "2024-08-31 2:30pm")); check("times of day, 12 or 24 hour, are read", identical(d$value, c("2024-08-31 14:30", "2024-08-31 14:30:15", "2024-08-31 14:30")) || (d$value[1] == "2024-08-31 14:30" && d$value[2] == "2024-08-31 14:30:15"))
d <- imp_dates(c("2024-02-30", "31/04/2024", "soon", "13/13/2024")); check("impossible dates and words are not dates (kept as typed, listed)", all(d$bad))
d <- imp_dates(c("44927", "45000.75", "123", "99999")); check("Excel serial numbers become dates; other numbers are not dates", d$serial == 2 && d$value[1] == "2023-01-01" && all(d$bad[3:4]))

cat("numbers\n")
r <- imp_numbers(c("60.1", "60,1", "0,25")); check("a decimal comma is read when the column uses one", r$comma && identical(r$value, c("60.1", "60.1", "0.25")) && !any(r$bad))
r <- imp_numbers(c("1,234.5", "2,000", "12")); check("thousands separators are removed, with a count so it can be warned about", r$thousands == 2 && identical(r$value, c("1234.5", "2000", "12")))
r <- imp_numbers(c("1.234,5", "12,5")); check("European thousands (1.234,5) are read", identical(r$value, c("1234.5", "12.5")))
r <- imp_numbers(c("−5.2", "-5.2", " 3 ")); check("the typographic minus is read", identical(r$value, c("-5.2", "-5.2", "3")))
r <- imp_numbers(c("45 cm", "45cm", "45"), "cm"); check("the field's own unit after the number is removed", identical(r$value, c("45", "45", "45")))
r <- imp_numbers(c("12", "abc", "1..2")); check("what is not a number is listed", identical(r$bad, c(FALSE, TRUE, TRUE)))

r <- imp_numbers(c("1 234,5", "12 345,67", "9")); check("a space as the thousands separator is read (1 234,5)", identical(r$value, c("1234.5", "12345.67", "9")) && r$comma)
d <- imp_dates(c("2024/08/31", "31 August 2024 14:00", "8/31/24 2:30 PM", "August 31st, 2024")); check("more date styles: slashes with the year first, a long month with a time, month first with two-digit year and AM/PM, ordinals",
  identical(d$value[c(1, 2, 4)], c("2024-08-31", "2024-08-31 14:00", "2024-08-31")) && d$value[3] == "2024-08-31 14:30")
x <- rd(wr("multiline.csv", c("Serial,Notes", "1,\"line one", "line two\"", "2,ok"))); check("a quoted cell with a line break inside stays one cell", nrow(x) == 2 && grepl("line one", x$Notes[1]) && grepl("line two", x$Notes[1]))
x <- rd(wr("tabs.csv", c("Serial\tNotes", "1\t\"a\tb\"", "2\tc"))); check("a tab inside a quoted cell of a tab file stays in the cell", nrow(x) == 2 && x$Notes[1] == "a\tb" || x$Notes[1] == "a b")
wide <- paste(paste0("c", seq_len(600)), collapse = ","); check("a table with hundreds of columns is refused plainly, not matched blindly", grepl("columns", err(rd(wr("wide.csv", c(wide, wide))))))
big <- wr("big.csv", c("Serial,Site", rep("1,A", 200100))); check("a table over 200,000 rows is refused as the wrong file", grepl("rows", err(rd(big))))
x <- rd(wr("quotes_bad.csv", c("Serial,Notes", "1,\"unterminated", "2,fine", "3,fine"))); check("an unterminated quote does not lose the whole file", nrow(x) >= 1)

cat("preparing and checking an import\n")
chk <- function(x, map, mode = "add", existing = NULL, order = "auto") { pr <- imp_prepare(x, map, spec, order); list(p = pr, i = imp_check(pr, map, spec, existing, mode)) }
sev <- function(i, s) i[severity == s]
x <- data.table(`Logger SN` = c("2.01E+07", "123", ""), `Where` = c("A", "B", "C"), `Date in` = c("03/04/2024", "05/06/2024", "07/08/2024"))
r <- chk(x, c("serial", "station", "from")); check("a serial Excel turned into scientific notation is an error, not a silent wrong key", any(grepl("scientific", sev(r$i, "error")$message)))
check("slash dates that cannot be told apart are an error that asks which order", any(grepl("day/month or month/day", sev(r$i, "error")$message)))
r <- chk(x, c("serial", "station", "from"), order = "dmy"); check("choosing the order clears the error and the dates are written as ISO", !any(grepl("day/month or month/day", sev(r$i, "error")$message)) && r$p$x$`Date in`[1] == "2024-04-03")
x <- data.table(S = c("1", "2"), A = c("x", "y"), B = c("p", "q"))
r <- chk(x, c("serial", "station", "station")); check("two columns on one field is an error that names both columns", any(grepl("Two columns", sev(r$i, "error")$message) & grepl("\"A\"", sev(r$i, "error")$message) & grepl("\"B\"", sev(r$i, "error")$message)))
check("the same mistake stops meta_from_import() too (nothing is overwritten silently)", grepl("same field", err(meta_from_import(x, c("serial", "station", "station"), spec))))
r <- chk(x, c("", "", "")); check("nothing matched is an error", any(grepl("No column is matched", sev(r$i, "error")$message)))
r <- chk(x, c("", "station", "")); check("no column for the key warns that rows are left aside (add)", any(grepl("left aside", sev(r$i, "warning")$message)))
r <- chk(x, c("", "station", ""), mode = "update"); check("... and is an error when updating (nothing to match rows on)", any(grepl("Updating needs it", sev(r$i, "error")$message)))
x <- data.table(S = c("1", "", "1", "2"), A = c("x", "y", "z", "w"))
r <- chk(x, c("serial", "station")); check("blank keys and repeated keys are counted in plain words", any(grepl("no Serial number", r$i$message)) && any(grepl("more than once", r$i$message)))
r <- chk(x, c("serial", "station"), existing = data.table(serial = c("2", "9")), mode = "add"); check("a key already in the table warns when adding", any(grepl("already in the table", sev(r$i, "warning")$message)))
r <- chk(x, c("serial", "station"), existing = data.table(serial = c("2", "9")), mode = "update"); check("... and is just a note when updating", any(grepl("already in the table", sev(r$i, "note")$message)))
x <- data.table(S = c("1", "2", "3"), Lat = c("61,5", "x", "62,0"))
r <- chk(x, c("serial", "latitude")); check("an unreadable number is listed with an example and what the app will do; the rest are converted", any(grepl("not a number", sev(r$i, "warning")$message) & grepl("\"x\"", sev(r$i, "warning")$message)) && r$p$x$Lat[1] == "61.5")
r <- chk(x, c("serial", "+Weather")); check("a new column of one's own is announced", any(grepl("will be added", r$i$message)))
x <- data.table(S = c("1", "2"), Lat = c("61.5", "62")); r <- chk(x, c("serial", "latitude")); check("a clean import has no errors or warnings", !nrow(sev(r$i, "error")) && !nrow(sev(r$i, "warning")))
x <- data.table(S = c("123.0", "456.0"), A = c("a", "b")); r <- chk(x, c("serial", "station")); check("serials written 123.0 lose the .0, with a note", identical(r$p$x$S, c("123", "456")))
x <- data.table(S = c("'123", "456"), A = c("a", "b")); r <- chk(x, c("serial", "station")); check("Excel's leading apostrophe is removed", r$p$x$S[1] == "123")
cs <- data.table(field = c("id", "kind"), label = c("ID", "Kind"), type = c("text", "choice"), choices = c("", "water|baro"), identifies = c("TRUE", "FALSE")); cs <- meta_defaults(cs)
pr <- imp_prepare(data.table(ID = c("a", "b", "c"), Kind = c("Water", "BARO", "wells")), c("id", "kind"), cs)
check("a choice field takes the choice whatever the case, and lists what is not one of them", identical(pr$x$Kind[1:2], c("water", "baro")) && any(grepl("wells", pr$issues$message)))

cat("set-up tables that declare no fields\n")
ent <- list(file = "time_corrections.csv", rules = list(required = "serial", choices = list(profile = c("shallow", "deep"))))
sp <- meta_defaults(import_spec_guess(c("serial", "start", "end", "offset_hours", "profile", "notes", "site"), ent))
check("types are judged from the column names and the table's rules", identical(sp$type, c("text", "date", "date", "number", "choice", "text", "text")) && sp$identifies[1] == "TRUE" && sp$choices[5] == "shallow|deep")
x <- data.table(`Serial Number` = c("123", "456"), `Start date` = c("31/08/2024", "01/09/2024"), `End date` = c("", "05/09/2024"), `Offset hours` = c("-1,5", "2"), Profile = c("DEEP", "mid"), Comments = c("a", "b"))
m <- imp_guess(names(x), sp); check("headings are matched to such a table's columns (serial number, start date, comments)", identical(m$field[c(1, 2, 3, 6)], c("serial", "start", "end", "notes")))
pr <- imp_prepare(x, c("serial", "start", "end", "offset_hours", "profile", "notes"), sp)
check("day-first dates, decimal commas and choices in such a table are put in order, and a value outside the choices is listed", identical(pr$x$`Start date`, c("2024-08-31", "2024-09-01")) && pr$x$`Offset hours`[1] == "-1.5" && pr$x$Profile[1] == "deep" && any(grepl("\"mid\"", pr$issues$message)))

cat("the whole path, as the screen runs it\n")
p <- wr("real.csv", c("Deployment log,,,,", "Logger SN;Where;Lat;Lon;Start;End", "", "2.0E+07;ST01;60,10;-120,10;31/08/2024;", "x"))
x <- tryCatch(rd(p), error = function(e) e); check("a messy semicolon file with a title line, decimal commas, day-first dates and blanks reads without error", !inherits(x, "error") && nrow(x) >= 1)
p <- wr("good.csv", c("Instrument serial no,Location,Latitude (dd),Longitude (dd),Date installed,Date removed,Comments", "1000002,ST01,60.1,-120.1,2023-06-01,2023-09-20,ok", "1000002,ST02,60.11,-120.11,2023-09-25,,moved", "1000003,Upland,60.2,-120.2,31/08/2024,,x"))
x <- rd(p); m <- imp_guess(names(x), spec)
check("a differently named but ordinary deployment file matches every column", identical(m$field, c("serial", "station", "latitude", "longitude", "from", "to", "notes")))
pr <- imp_prepare(x, m$field, spec); ck <- imp_check(pr, m$field, spec)
check("it prepares, with no error: its slash dates include a 31, which settles day first", !nrow(ck[severity == "error"]) && pr$x[[5]][3] == "2024-08-31")
rows <- meta_from_import(pr$x, m$field, spec)$rows; check("and meta_from_import() builds the rows from the prepared table", nrow(rows) == 3 && rows$serial[1] == "1000002" && rows$from[3] == "2024-08-31")

cat("fuzz: 600 random awkward files; nothing may end in an R-internal error\n")
set.seed(42)
pool <- c("Serial", "serial no", "Site", "Station", "From", "To", "Lat", "Lon", "Notes", "Depth (m)", "", " ", "N/A", "-", "1", "2.5", "1,5", "1,234.5", "0001", "2.01E+07", "31/08/2024", "03/04/2024", "2024-02-30", "2024-05-01 14:30", "45531", "°C", "café", "a,b", "\"q\"", "'x", "#REF!", "x y", "− 5", "0", "99999999999999999999", "NA", "TRUE", "e", "中文", "a\"b", "=1+1")
sepc <- c(",", ";", "\t", "|", ",", ",")
internal <- "subscript|object '|argument|non-numeric|undefined columns|invalid .*(type|argument|format)|missing value|differing|cannot coerce|replacement has|attempt to|unused|could not find|not a (valid|data)|is not an|NULL|length\\(|dims|\\$ operator|incorrect number"
bad <- character()
for (it in seq_len(600)) {
  nc <- sample(1:7, 1); nr <- sample(0:12, 1); sp <- sample(sepc, 1)
  cell <- function() { v <- sample(pool, 1); if (grepl("[,;\t|\"]", v) && runif(1) < 0.7) paste0("\"", gsub("\"", "\"\"", v), "\"") else v }
  ln <- vapply(seq_len(nr + sample(0:3, 1)), function(i) paste(vapply(seq_len(max(1, nc + sample(-2:2, 1))), function(j) cell(), ""), collapse = sp), "")
  if (runif(1) < 0.3) ln <- c(paste(sample(pool, sample(1:3, 1)), collapse = sp), "", ln)
  raw <- charToRaw(paste(ln, collapse = sample(c("\n", "\r\n"), 1)))
  if (runif(1) < 0.1) raw <- c(raw, as.raw(sample(0:255, 5)))
  if (runif(1) < 0.05) raw <- raw[seq_len(sample(0:length(raw), 1))]
  p <- file.path(tmp, "fz.csv"); writeBin(raw, p)
  res <- tryCatch({ x <- meta_import_read(p, name = "fz.csv", spec = spec, header_row = if (runif(1) < 0.2) sample(1:5, 1) else NULL)
      g <- imp_guess(names(x), spec); map <- g$field
      if (runif(1) < 0.5) map <- sample(c(DEPLOY_FIELDS$field, "", "+New"), ncol(x), TRUE)
      pr <- imp_prepare(x, map, spec, sample(c("auto", "dmy", "mdy"), 1)); ck <- imp_check(pr, map, spec, data.table(serial = c("1", "2")), sample(c("add", "update", "replace"), 1))
      if (!nrow(ck[severity == "error"])) meta_from_import(pr$x, map, spec)
      "" }, error = function(e) conditionMessage(e))
  if (nzchar(res) && grepl(internal, res, ignore.case = TRUE) && !grepl("Two columns|same field", res)) bad <- c(bad, res)
}
msg <- if (length(bad)) paste0(": ", paste(utils::head(unique(substr(bad, 1, 90)), 3), collapse = " | ")) else ""
check(paste0("600 random files: no internal R error (", length(bad), " found", msg, ")"), length(bad) == 0)

cat("the screen (Shiny server test: the person's choices, in order)\n")
if (requireNamespace("shiny", quietly = TRUE)) {
  suppressMessages(library(shiny)); source(file.path(CORE_DIR, "metasheet_ui.R"), local = TRUE)
  put_log <- new.env(); mem_log <- new.env(); put_log$n <- 0L
  IMP <- NULL; mk <- function() { ex <- data.table(serial = c("5"), station = "old", from = "2020-01-01")
    function(input, output, session) { IMP <<- table_import_server(input, output, session, reactive(spec), put = function(new, mode, s) { put_log$rows <- new; put_log$mode <- mode; put_log$n <- put_log$n + 1L; TRUE },
      modes = c("add", "update", "replace"), new_cols = TRUE, existing = function() ex, memory = list(get = function() data.table(heading = "Pit Label", field = "station"), put = function(h, m) { mem_log$h <- h; mem_log$m <- m })) } }
  up <- function(p) list(name = basename(p), datapath = p, size = file.size(p), type = "text/csv")
  p <- wr("ui1.csv", c("Logger SN,Pit Label,Date in,Date out,Weather", "1000002,ST01,03/04/2024,,sunny", "1000012,ST02,05/06/2024,07/08/2024,rain"))
  testServer(mk(), {
    session$setInputs(import = 1, imp_file = up(p), imp_mode = "add")
    x <- IMP$incoming(); check("the screen reads the file and matches by heading and by what was remembered (Hole is Station)", !is.null(x) && identical(IMP$guess()$field[1:4], c("serial", "station", "from", "to")) && IMP$guess()$how[2] == "memory")
    session$setInputs(map_1 = "serial", map_2 = "station", map_3 = "from", map_4 = "to", map_5 = "+Weather")
    r <- IMP$checked(); check("with slash dates nothing can settle, the screen reports the error and Put them in would be refused", any(grepl("day/month or month/day", r$issues[severity == "error"]$message)))
    session$setInputs(imp_go = 1); check("pressing Put them in with an error writes nothing", put_log$n == 0L)
    session$setInputs(imp_dates = "dmy"); r <- IMP$checked(); check("choosing day first clears it; the dates are written as ISO", !nrow(r$issues[severity == "error"]) && r$prep$x[[3]][1] == "2024-04-03")
    session$setInputs(imp_go = 2); check("then the rows go in once, with the new Weather column and the converted dates", put_log$n == 1L && put_log$rows$from[1] == "2024-04-03" && "weather" %in% names(put_log$rows) && put_log$mode == "add")
    check("what was matched is handed to the memory", identical(mem_log$h[1:2], c("Logger SN", "Pit Label")) && mem_log$m[2] == "station")
  })
  p2 <- wr("ui2.csv", c("Notes only,Weather", "a,b"))
  testServer(mk(), {
    session$setInputs(import = 1, imp_file = up(p2), imp_mode = "update"); session$setInputs(map_1 = "notes", map_2 = "")
    r <- IMP$checked(); check("updating without a key column is an error on the screen", any(grepl("Updating needs it", r$issues[severity == "error"]$message)))
    session$setInputs(imp_go = 1); check("and nothing is written", put_log$n == 1L)
  })
  p3 <- wr("ui3.csv", raw(0))
  testServer(mk(), { session$setInputs(import = 1, imp_file = up(p3)); check("an empty file puts a plain message on the screen, not an R error", grepl("empty", IMP$trouble()) && is.null(IMP$incoming())) })
  testServer(mk(), {
    session$setInputs(paste = 1); session$setInputs(paste_txt = "Serial\tStation\tFrom\n1\tA\t2024-05-01\n2\tB\t2024-05-02")
    check("pasted rows with headings are matched", !is.null(IMP$incoming()) && identical(IMP$guess()$field, c("serial", "station", "from")))
    session$setInputs(paste_txt = "7\tZ\t2024-05-01"); check("a pasted line with no headings is taken as data, in the table's order, and said so", nrow(IMP$incoming()) == 1 && IMP$guess()$how[1] == "order" && any(grepl("not a row of headings", attr(IMP$incoming(), "notes"))))
    session$setInputs(paste_txt = ""); check("clearing the box clears the screen", is.null(IMP$incoming()))
  })
}

if (length(RES$fail)) { cat("\n", length(RES$fail), "FAILED:\n"); cat(paste0("  - ", RES$fail), sep = "\n"); quit(status = 1) } else cat("\n", RES$ok, "passed, 0 failed\n")
